// Activation LUTs for the MGR1 kernels, bit-identical to
// model/integer_oracle/oracle.py (Phase 4 frozen contract).
//
// The table contents live in activation_lut_contents.h, GENERATED by
// tools/gen_lut_header.py directly from the oracle; regeneration equality is
// enforced by tests/test_lut_header.py.  This removes the runtime double
// math from the synthesizable path entirely - the tables are ROMs.

#include "mgr1_types.h"

#include "activation_lut_contents.h"

namespace mgr1 {

// Kept for API compatibility with earlier callers; the tables are generated
// constants now and need no construction.
void build_luts() {}

int sigmoid_q15(int i) {
    return MGR1_SIGMOID_LUT[sat(-32768, 32767, i) + 32768];
}

int tanh_q15(int i) {
    return MGR1_TANH_LUT[sat(-32768, 32767, i) + 32768];
}

}  // namespace mgr1
